#include <vector>
#include <string>
#include<curses.h>

using namespace std;

class RoomList {

    private:

        vector<string> topicList;
        int highlight;

    public:

        RoomList(){
            topicList ={"General", "Sports","Programming","Music","Random"};
            int highlight = 0;
        }

        void selectUp(){
            highlight=(highlight == 0)? topicList.size() -1: highlight-1;
        }

        void selectDown(){
            highlight=(highlight == topicList.size()-1)? 0: highlight+1;

        }

        void drawLeft(WINDOW* leftInner){
            int length = topicList.size();

            for(int i=0; i<length ; ++i){

                if(i == highlight){
                    //start_color();
                    attron(A_REVERSE);
                        mvwprintw(leftInner, (i+3) ,1,"> %s",topicList[i].c_str());
                    attroff(A_REVERSE);

                }else{
                    mvwprintw(leftInner, (i+3) ,1,topicList[i].c_str());
                }

            }

            wrefresh(leftInner);

        }

};

