#include <vector>
#include <string>
#include <curses.h>

using namespace std;

class MessageArea {

    private:

        vector<string> messages;

    public:

        MessageArea(){

        }

        void textInput( string input ){

            messages.push_back(input);
        }

        void drawChat(WINDOW* mainInner){

            werase(mainInner);


            int numMessages = messages.size();

            int chatHeight,chatWidth;

            getmaxyx(mainInner,chatHeight,chatWidth);

                //the function max use a floor of zero, and ruturns where we shoudl start inside the
                //vector pending on screen size
                int displayStart= max(0, static_cast<int>(messages.size()) - chatHeight);

            int rowTotal=0;

            for(int i=displayStart; i< numMessages; i++){

                mvwprintw( mainInner, rowTotal++, 1, messages[i].c_str());

            }
                wrefresh(mainInner);
        }

};

